CREATE TABLE "catatan_bbm" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "catatan_bbm_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id_kendaraan" bigint NOT NULL,
	"id_sopir" bigint,
	"id_perjalanan" bigint,
	"tanggal" date NOT NULL,
	"odometer_km" integer,
	"liter" numeric(8, 2) NOT NULL,
	"total_rp" bigint NOT NULL,
	"penuh" boolean DEFAULT false NOT NULL,
	"catatan" varchar(255),
	"id_pengguna" bigint NOT NULL,
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"batal_pada" timestamp with time zone,
	"alasan_batal" varchar(255),
	"dibatalkan_oleh" bigint,
	CONSTRAINT "chk_catatan_bbm_angka" CHECK (liter > 0 and total_rp >= 0 and (odometer_km is null or odometer_km >= 0)),
	CONSTRAINT "chk_catatan_bbm_batal" CHECK ((batal_pada is null) = (alasan_batal is null))
);
